export type HotFileWriteOwner = string;

export type HotFileWriteToken = string;

export type HotFileWriteConflict = {
  readonly kind: "conflict";
  readonly path: string;
  readonly holder: {
    readonly owner: HotFileWriteOwner;
    readonly token: HotFileWriteToken;
  };
};

export type HotFileWriteClaim =
  | {
      readonly ok: true;
      readonly path: string;
      readonly owner: HotFileWriteOwner;
      readonly token: HotFileWriteToken;
      readonly reentrant: boolean;
    }
  | HotFileWriteConflict;

export type HotFileWriteReleaseResult =
  | { readonly ok: true; readonly released: true }
  | { readonly ok: false; readonly released: false; readonly reason: "not-found" | "owner-mismatch" | "token-mismatch" };

export type HotFileWriteLease = {
  readonly path: string;
  readonly owner: HotFileWriteOwner;
  readonly token: HotFileWriteToken;
};

type ActiveClaim = {
  owner: HotFileWriteOwner;
  token: HotFileWriteToken;
};

/**
 * CAS-style ownership registry for hot-file mutations.
 *
 * The registry deliberately does not schedule work. Mutation serialization remains
 * the responsibility of the existing per-file mutation queue. This class only
 * makes the write lease and its ownership token observable.
 */
export class HotFileWriteOwnerRegistry {
  readonly #claims = new Map<string, ActiveClaim>();

  claim(path: string, owner: HotFileWriteOwner, token?: HotFileWriteToken): HotFileWriteClaim {
    if (!path) throw new TypeError("path must not be empty");
    if (!owner) throw new TypeError("owner must not be empty");

    const current = this.#claims.get(path);
    if (current) {
      if (current.owner === owner) {
        return {
          ok: true,
          path,
          owner,
          token: current.token,
          reentrant: true,
        };
      }
      return {
        kind: "conflict",
        path,
        holder: { owner: current.owner, token: current.token },
      };
    }

    const issuedToken = token ?? createHotFileWriteToken();
    this.#claims.set(path, { owner, token: issuedToken });
    return {
      ok: true,
      path,
      owner,
      token: issuedToken,
      reentrant: false,
    };
  }

  release(path: string, owner: HotFileWriteOwner, token: HotFileWriteToken): HotFileWriteReleaseResult {
    const current = this.#claims.get(path);
    if (!current) return { ok: false, released: false, reason: "not-found" };
    if (current.owner !== owner) return { ok: false, released: false, reason: "owner-mismatch" };
    if (current.token !== token) return { ok: false, released: false, reason: "token-mismatch" };

    this.#claims.delete(path);
    return { ok: true, released: true };
  }

  rollback(path: string, owner: HotFileWriteOwner, token: HotFileWriteToken): HotFileWriteReleaseResult {
    return this.release(path, owner, token);
  }

  holder(path: string): HotFileWriteLease | undefined {
    const current = this.#claims.get(path);
    return current ? { path, owner: current.owner, token: current.token } : undefined;
  }

  isOwner(path: string, owner: HotFileWriteOwner, token?: HotFileWriteToken): boolean {
    const current = this.#claims.get(path);
    if (!current || current.owner !== owner) return false;
    return token === undefined || current.token === token;
  }
}

export const hotFileWriteOwners = new HotFileWriteOwnerRegistry();

export function claimHotFileWriteOwner(
  path: string,
  owner: HotFileWriteOwner,
  token?: HotFileWriteToken,
): HotFileWriteClaim {
  return hotFileWriteOwners.claim(path, owner, token);
}

export function releaseHotFileWriteOwner(
  path: string,
  owner: HotFileWriteOwner,
  token: HotFileWriteToken,
): HotFileWriteReleaseResult {
  return hotFileWriteOwners.release(path, owner, token);
}

export function rollbackHotFileWriteOwner(
  path: string,
  owner: HotFileWriteOwner,
  token: HotFileWriteToken,
): HotFileWriteReleaseResult {
  return hotFileWriteOwners.rollback(path, owner, token);
}

export function getHotFileWriteHolder(path: string): HotFileWriteLease | undefined {
  return hotFileWriteOwners.holder(path);
}

export function isHotFileWriteOwner(
  path: string,
  owner: HotFileWriteOwner,
  token?: HotFileWriteToken,
): boolean {
  return hotFileWriteOwners.isOwner(path, owner, token);
}

export type MutationQueueRunner<T> = (path: string, operation: () => Promise<T> | T) => Promise<T>;

export type HotFileMutationResult<T> =
  | { readonly ok: true; readonly value: T; readonly lease: HotFileWriteLease }
  | { readonly ok: false; readonly error: unknown; readonly conflict: HotFileWriteConflict };

/**
 * Runs a mutation in the caller's existing per-file mutation queue while the
 * caller holds a verified ownership lease. The queue is required so this
 * module cannot accidentally introduce a second scheduler.
 */
export async function runHotFileMutation<T>(
  path: string,
  owner: HotFileWriteOwner,
  mutationQueue: MutationQueueRunner<T>,
  operation: () => Promise<T> | T,
): Promise<HotFileMutationResult<T>> {
  const claim = claimHotFileWriteOwner(path, owner);
  if (!claim.ok) {
    return { ok: false, error: new HotFileWriteOwnershipError(claim), conflict: claim };
  }

  const lease: HotFileWriteLease = { path, owner, token: claim.token };
  try {
    const value = await mutationQueue(path, operation);
    releaseHotFileWriteOwner(path, owner, claim.token);
    return { ok: true, value, lease };
  } catch (error) {
    rollbackHotFileWriteOwner(path, owner, claim.token);
    throw error;
  }
}

export class HotFileWriteOwnershipError extends Error {
  readonly conflict: HotFileWriteConflict;

  constructor(conflict: HotFileWriteConflict) {
    super(`hot-file write ownership conflict for ${conflict.path}; holder is ${conflict.holder.owner}`);
    this.name = "HotFileWriteOwnershipError";
    this.conflict = conflict;
  }
}

function createHotFileWriteToken(): HotFileWriteToken {
  const cryptoObject = (globalThis as { crypto?: { randomUUID?: () => string } }).crypto;
  if (cryptoObject?.randomUUID) return cryptoObject.randomUUID();

  // The fallback is process-local and sufficient for CAS token uniqueness; it
  // does not perform network or process side effects.
  const random = Math.random().toString(36).slice(2);
  return `${Date.now().toString(36)}-${random}`;
}

