    return this.release(path, owner, token);
  }

  holder(path: string): HotFileWriteLease | undefined {
    const current = this.#claims.get(path);
    return current ? { path, owner: current.owner, token: current.token } : undefined;
  }

  isOwner(path: string, owner: HotFileWriteOwner, token?: HotFileWriteToken): boolean {
    const current = this.#claims.get(path);
    if (!current || current.owner !== owner) return false;
    return token === undefined || current.token === token;
  }
